// Asserts the Swift translator reproduces the Python reference exactly, using
// test-vectors/hud_golden.json (generated by sim/navhud/golden.py).
import XCTest
@testable import NavHUDKit

final class TranslatorGoldenTests: XCTestCase {

    struct Golden: Decodable {
        struct DistanceRow: Decodable {
            let meters: Double
            let text: String
        }
        struct Case: Decodable {
            let label: String
            let event: NavEvent
            let frames: [String: HudFrame]
        }
        let profiles: [String]
        let distanceText: [DistanceRow]
        let cases: [Case]

        enum CodingKeys: String, CodingKey {
            case profiles
            case distanceText = "distance_text"
            case cases
        }
    }

    static func loadGolden() throws -> Golden {
        var url = URL(fileURLWithPath: #filePath)
        for _ in 0..<5 { url.deleteLastPathComponent() }  // -> bmw-g30-hud/
        url.appendPathComponent("test-vectors/hud_golden.json")
        return try JSONDecoder().decode(Golden.self, from: Data(contentsOf: url))
    }

    func testProfilesExistInSwift() throws {
        let golden = try Self.loadGolden()
        XCTAssertFalse(golden.profiles.isEmpty)
        for name in golden.profiles {
            XCTAssertNotNil(HudProfile.named(name), "Swift is missing profile \(name)")
        }
    }

    func testDistanceTextMatchesReference() throws {
        let golden = try Self.loadGolden()
        XCTAssertGreaterThan(golden.distanceText.count, 10)
        for row in golden.distanceText {
            XCTAssertEqual(Translator.usDistanceText(row.meters), row.text,
                           "distance text differs at \(row.meters) m")
        }
    }

    func testEveryCaseMatchesReference() throws {
        let golden = try Self.loadGolden()
        XCTAssertGreaterThan(golden.cases.count, 40)
        var compared = 0
        for c in golden.cases {
            XCTAssertNoThrow(try c.event.validate(), "\(c.label): golden event invalid")
            for (profileName, expected) in c.frames {
                let profile = try XCTUnwrap(HudProfile.named(profileName))
                let got = Translator(profile: profile).translate(c.event)
                let ctx = "\(c.label) / \(profileName)"
                XCTAssertEqual(got.profileName, expected.profileName, ctx)
                XCTAssertEqual(got.visible, expected.visible, ctx)
                XCTAssertEqual(got.arrow, expected.arrow, ctx)
                XCTAssertEqual(got.distanceText, expected.distanceText, ctx)
                XCTAssertEqual(got.distanceFraction, expected.distanceFraction, accuracy: 1e-12, ctx)
                XCTAssertEqual(got.label, expected.label, ctx)
                XCTAssertEqual(got.roundaboutExit, expected.roundaboutExit, ctx)
                XCTAssertEqual(got.lanes, expected.lanes, ctx)
                XCTAssertEqual(got.etaText, expected.etaText, ctx)
                XCTAssertEqual(got.banner, expected.banner, ctx)
                compared += 1
            }
        }
        XCTAssertEqual(compared, golden.cases.count * golden.profiles.count)
    }

    func testTranslatedArrowIsAlwaysShowable() throws {
        for profile in HudProfile.all {
            for m in Maneuver.allCases {
                let frame = Translator(profile: profile)
                    .translate(NavEvent(eventId: 1, maneuver: m, distanceToManeuverM: 100))
                XCTAssertTrue(profile.canShow(frame.arrow), "\(profile.name) can't show \(frame.arrow)")
            }
        }
    }

    func testEtaFormattingUsesInjectedTimeZone() throws {
        let utc = try XCTUnwrap(TimeZone(identifier: "UTC"))
        // 2026-11-10 17:05:00 UTC
        XCTAssertEqual(Translator.formatEta(1_794_330_300, timeZone: utc), "5:05 PM")
        XCTAssertEqual(Translator.formatEta(0, timeZone: utc), "12:00 AM")
        let ev = NavEvent(eventId: 1, maneuver: .turnLeft, distanceToManeuverM: 300,
                          etaEpochS: 1_794_330_300)
        XCTAssertEqual(Translator(profile: .g30KOMBI, timeZone: utc).translate(ev).etaText, "5:05 PM")
        XCTAssertEqual(Translator(profile: .g30HUD, timeZone: utc).translate(ev).etaText, "")
    }

    func testEventJSONRoundTrip() throws {
        let ev = NavEvent(eventId: 7, kind: .reroute, maneuver: .roundabout,
                          distanceToManeuverM: 120.5, roadName: "Park Blvd",
                          roundaboutExit: 2, distanceRemainingM: 900, lanes: ["l", "s"])
        let data = try JSONEncoder().encode(ev)
        XCTAssertEqual(try JSONDecoder().decode(NavEvent.self, from: data), ev)
        // keys are snake_case, like the Python reference
        let obj = try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? [String: Any])
        XCTAssertNotNil(obj["distance_to_maneuver_m"])
        XCTAssertNotNil(obj["roundabout_exit"])
    }

    func testValidationMatchesReferenceRules() {
        XCTAssertThrowsError(try NavEvent(eventId: -1).validate())
        XCTAssertThrowsError(try NavEvent(eventId: 1, distanceToManeuverM: -5).validate())
        XCTAssertThrowsError(try NavEvent(eventId: 1, maneuver: .roundabout, roundaboutExit: 0).validate())
        XCTAssertThrowsError(try NavEvent(eventId: 1, distanceRemainingM: -1).validate())
        XCTAssertNoThrow(try NavEvent(eventId: 0).validate())
    }
}
